const restBase = 'https://ifnznfspkjayhnooncrv.supabase.co/rest/v1';
const body = $json.body || {};
const envKey = String(body.environmentKey || body.environment?.environmentKey || 'local');
const integrationBody = body.integration || {};
const integrationKey = String(body.integrationKey || integrationBody.integrationKey || '').trim();
const now = new Date().toISOString();
const actor = body.updatedBy || body.actorName || 'n8n';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
function withActor(payload) {
  if (uuidPattern.test(String(body.updatedBy || ''))) payload.updated_by = body.updatedBy;
  if (uuidPattern.test(String(body.actorUserId || ''))) payload.updated_by = body.actorUserId;
  return payload;
}
if (integrationKey) {
  const payload = withActor({ updated_at: now });
  if (typeof body.enabled === 'boolean') payload.enabled = body.enabled;
  if (typeof integrationBody.enabled === 'boolean') payload.enabled = integrationBody.enabled;
  if (body.config && typeof body.config === 'object') payload.config = body.config;
  if (integrationBody.config && typeof integrationBody.config === 'object') payload.config = integrationBody.config;
  if (body.secretRefs && typeof body.secretRefs === 'object') payload.secret_refs = body.secretRefs;
  if (integrationBody.secretRefs && typeof integrationBody.secretRefs === 'object') payload.secret_refs = integrationBody.secretRefs;
  if (body.status) payload.status = body.status;
  if (integrationBody.status) payload.status = integrationBody.status;
  if (Object.keys(payload).length <= 1) throw new Error('No supported integration settings fields were provided');
  return [{ json: { target: 'integration', url: `${restBase}/qops_integration_settings?environment_key=eq.${encodeURIComponent(envKey)}&integration_key=eq.${encodeURIComponent(integrationKey)}`, payload, audit: { actor_name: actor, action: 'SETTINGS_INTEGRATION_UPDATED', entity_type: 'integration_settings', entity_id: integrationKey, status: 'success', details: `Updated ${integrationKey} settings for ${envKey}`, metadata: { source: 'ui', environmentKey: envKey, integrationKey, changedKeys: Object.keys(payload) } } } }];
}
const environment = body.environment || body;
const payload = withActor({ updated_at: now });
if (environment.displayName !== undefined) payload.display_name = environment.displayName;
if (environment.apiBaseUrl !== undefined) payload.api_base_url = environment.apiBaseUrl;
if (environment.n8nBaseUrl !== undefined) payload.n8n_base_url = environment.n8nBaseUrl;
if (environment.webhookPaths !== undefined) payload.webhook_paths = environment.webhookPaths;
if (environment.isActive !== undefined) payload.is_active = Boolean(environment.isActive);
if (Object.keys(payload).length <= 1) throw new Error('No supported environment settings fields were provided');
return [{ json: { target: 'environment', url: `${restBase}/qops_environment_settings?environment_key=eq.${encodeURIComponent(envKey)}`, payload, audit: { actor_name: actor, action: 'SETTINGS_ENVIRONMENT_UPDATED', entity_type: 'environment_settings', entity_id: envKey, status: 'success', details: `Updated environment settings for ${envKey}`, metadata: { source: 'ui', environmentKey: envKey, changedKeys: Object.keys(payload) } } } }];

const prepared = $('Prepare Settings Patch').first().json;
const updated = $input.first().json || {};
return [{ json: { ok: true, target: prepared.target, updated, audit: prepared.audit } }];
